import unicodedata


class ParseException(Exception):
    pass


class AlreadySelectedException(ParseException):
    def __init__(self, message: str = ""):
        super().__init__(message)


class UnrecognizedOptionException(ParseException):
    def __init__(self, message: str, option: Optional[str] = None):
        super().__init__(message)
        self._option = option

    def getOption(self) -> Optional[str]:
        return self._option


class AmbiguousOptionException(UnrecognizedOptionException):
    def __init__(self, option: str, matching_options: Collection[str]):
        msg = f"Ambiguous option: '{option}'  (could be: " + ", ".join(f"'{opt}'" for opt in matching_options) + ")"
        super().__init__(msg, option)
        self._matching_options = list(matching_options)

    def getMatchingOptions(self) -> List[str]:
        return list(self._matching_options)


class MissingOptionException(ParseException):
    def __init__(self, missing_options: List):
        plural = "" if len(missing_options) == 1 else "s"
        msg = f"Missing required option{plural}: " + ", ".join(str(opt) for opt in missing_options)
        super().__init__(msg)
        self._missing_options = list(missing_options)

    def getMissingOptions(self) -> List:
        return list(self._missing_options)


class MissingArgumentException(ParseException):
    def __init__(self, option_or_message):
        if isinstance(option_or_message, Option):
            super().__init__(f"Missing argument for option: {option_or_message.getKey()}")
            self._option = option_or_message
        else:
            super().__init__(str(option_or_message))
            self._option = None

    def getOption(self) -> Optional['Option']:
        return self._option


