def _is_java_identifier_part(c: str) -> bool:
    if len(c) != 1:
        return False
    if c.isalnum():
        return True
    cat = unicodedata.category(c)
    return cat in ('Sc', 'Pc', 'Mn', 'Mc', 'Nl')


def _is_valid_opt(c: str) -> bool:
    return _is_java_identifier_part(c) or c in ('?', '@')


def _is_valid_char(c: str) -> bool:
    return _is_java_identifier_part(c) or c == '-'


def _validate_option(option: Optional[str]) -> Optional[str]:
    if option is None:
        return None
    if len(option) == 0:
        raise IllegalArgumentException("Empty option name.")
    if not _is_valid_opt(option[0]):
        raise IllegalArgumentException(f"Illegal option name '{option[0]}'.")
    if len(option) > 1:
        for ch in option[1:]:
            if not _is_valid_char(ch):
                raise IllegalArgumentException(f"The option '{option}' contains an illegal character : '{ch}'.")
    return option


def strip_leading_hyphens(s: Optional[str]) -> Optional[str]:
